train = ExampleData[{"MachineLearning", "FisherIris"}, "TrainingData"];
test = ExampleData[{"MachineLearning", "FisherIris"}, "TestData"];
cm = ClassifierMeasurements[Classify[train], test];
{cm["Accuracy"], cm["ConfusionMatrixPlot"]}

train = ExampleData[{"MachineLearning", "BostonHomes"}, "TrainingData"];
test = ExampleData[{"MachineLearning", "BostonHomes"}, "TestData"];
pm = PredictorMeasurements[Predict[train], test];
{pm["StandardDeviation"], pm["RSquared"], pm["ComparisonPlot"]}

